data.description:
{
input:"Defines draggable object configuration including element id, motion friction, and velocity threshold parameters",
behavior:"Generates client-side script that enables drag-and-throw interaction with inertia physics, applies DOM event handlers for movement, and triggers backend API calls based on release velocity or animation completion."
}

data.fnString:
async function processRequest(input) {
  const {
    id = 'object2',
    friction = 0.95,
    threshold = 5
  } = input.var;

  const clientJS = `
fetch('http://localhost:3001/deleterun/${input.runId}');

(function () {
  const object1 = document.getElementById('${id}');
  let isDragging = false;
  let offsetX = 0, offsetY = 0;
  let velX = 0, velY = 0;
  let lastX = 0, lastY = 0;
  let lastTime = 0;
  const FRICTION = ${Number(friction) || 0.95};
  const THRESHOLD = ${Number(threshold) || 5};
  let rafId = null;

  if (!object1) return;

  object1.style.cursor = 'grab';
  object1.style.userSelect = 'none';
  object1.style.transition = 'none';

  object1.addEventListener('mousedown', (e) => {
    isDragging = true;
    object1.style.cursor = 'grabbing';
    object1.style.transition = 'none';

    const rect = object1.getBoundingClientRect();
    offsetX = e.clientX - rect.left;
    offsetY = e.clientY - rect.top;

    velX = 0;
    velY = 0;
    lastX = parseFloat(object1.style.left) || object1.offsetLeft || 0;
    lastY = parseFloat(object1.style.top) || object1.offsetTop || 0;
    lastTime = performance.now();

    cancelAnimationFrame(rafId);
  });

  document.addEventListener('mousemove', (e) => {
    if (!isDragging) return;

    const now = performance.now();
    const parent = object1.parentElement;
    const parentRect = parent
      ? parent.getBoundingClientRect()
      : document.documentElement.getBoundingClientRect();

    const x = e.clientX - parentRect.left - offsetX;
    const y = e.clientY - parentRect.top - offsetY;

    if (lastTime > 0) {
      const dt = Math.max(1, now - lastTime) / 16;
      velX = (x - lastX) / dt;
      velY = (y - lastY) / dt;
    }

    lastX = x;
    lastY = y;
    lastTime = now;

    object1.style.position = 'absolute';
    object1.style.left = x + 'px';
    object1.style.top = y + 'px';
  });

  document.addEventListener('mouseup', () => {
    if (!isDragging) return;

    isDragging = false;
    object1.style.cursor = 'grab';

    if (velY < -THRESHOLD) {
      object1.style.transition = 'none';
      throwAnimation();
    } else {
      fetch('http://localhost:3001/runnew/${input.projectId}/check1');
    }
  });

  function throwAnimation() {
    const rect = object1.getBoundingClientRect();
    const parent = object1.parentElement;
    const parentRect = parent
      ? parent.getBoundingClientRect()
      : document.documentElement.getBoundingClientRect();

    let newX = (parseFloat(object1.style.left) || 0) + velX;
    let newY = (parseFloat(object1.style.top) || 0) + velY;

    if (newY < 0) newY = 0;
    if (newY + rect.height > parentRect.height) {
      newY = parentRect.height - rect.height;
    }

    object1.style.left = newX + 'px';
    object1.style.top = newY + 'px';

    velX *= FRICTION;
    velY *= FRICTION;

    if (Math.abs(velX) > 0.5 || Math.abs(velY) > 0.5) {
      rafId = requestAnimationFrame(throwAnimation);
    } else {
      fetch('http://localhost:3001/runnew/${input.projectId}/check1');
    }
  }
})();
`;

  return {
    status: "ready",
    clientJS,
  };
}

