data.fnString:
async function processRequest(input) {

  const objects = input.var.objects;
  console.log("inputTest", input.var.inputTest );
  console.log("CreatePanelController running(A)", objects.length);

  const clientJS = `
console.log("CreatePanelController running(B)");

const root = document.querySelector("#ms-apiresults-body");

const objs = `+ JSON.stringify(objects) +`;

const byId = {};

objs.forEach(cfg => {

  let el = document.getElementById(cfg.id);
  if (!el) {
    el = document.createElement(cfg.type === "button" ? "button" : "div");
    el.id = cfg.id;
  }
  byId[cfg.id] = el;

  if (cfg.bgimage) {
    el.style.backgroundImage = 'url("' + cfg.bgimage + '")';
    el.style.backgroundSize = "cover";
  }

  el.style.position = cfg.position || "absolute";
  el.style.left = (cfg.x || 0) + "px";
  el.style.top = (cfg.y || 0) + "px";
  el.style.width = (cfg.width || 50) + "px";
  el.style.height = (cfg.height || 50) + "px";
  el.style.backgroundColor = cfg.color || "none";
  el.style.color = cfg.textcolor || "black";
  el.style.zIndex = cfg.zIndex || "1000";
  el.style.borderRadius = cfg.type === "button" ? "8px" : "0";
  el.style.fontSize = "14px";
  el.style.fontWeight = "bold";
  if (cfg.styles) {
    Object.assign(el.style, cfg.styles);
  }

  if (cfg.label) {
    el.textContent = cfg.label;
  }

  let parentEl = root;
  if (cfg.parent) {
    parentEl = document.getElementById(cfg.parent);
    if (!parentEl) parentEl = root;
  }
  parentEl.appendChild(el);
});
`;

  return {
    status: "ready",
    clientJS
  };
}

