data.fnString:
async function processRequest(input) {
  const { target, moveDistance } = input.var;

  const clientJS = `
console.log('action component');

(function () {
  const targetId = '${target}';
  const step = ${Number(moveDistance) || 50};

  function moveBy(dx, dy) {
    console.log('moveBy');
    try {
      const el = document.getElementById(targetId);
      if (!el) return;

      if (!el.style.position || el.style.position === '') {
        el.style.position = 'absolute';
      }

      const px = (v) => {
        if (!v) return 0;
        return parseInt(String(v).replace('px', ''), 10) || 0;
      };

      let left = px(el.style.left) || el.offsetLeft || 0;
      let top = px(el.style.top) || el.offsetTop || 0;

      left += dx;
      top += dy;

      el.style.left = left + 'px';
      el.style.top = top + 'px';

      console.log('move ' + left + ', ' + top);

      fetch('http://localhost:3001/runnew/${input.projectId}/check1');
    } catch (e) {
      console.error(e);
    }
  }

  document.getElementById('button_up')?.addEventListener('click', () => moveBy(0, -step));
  document.getElementById('button_down')?.addEventListener('click', () => moveBy(0, step));
  document.getElementById('button_left')?.addEventListener('click', () => moveBy(-step, 0));
  document.getElementById('button_right')?.addEventListener('click', () => moveBy(step, 0));

  document.getElementById('button_start')?.addEventListener('click', () => {
    document.getElementById('showtext-time').textContent = '0';
    document.getElementById('showtext_mark').textContent = '0';
    document.getElementById('showtext_totalmark').textContent = '3';

    document.getElementById('start_screen').style.display = 'none';
    document.getElementById('game_screen').style.display = 'block';
    document.getElementById('result_screen').style.display = 'none';
  });

  document.getElementById('button_skip')?.addEventListener('click', () => {
    document.getElementById('start_screen').style.display = 'none';
    document.getElementById('game_screen').style.display = 'none';
    document.getElementById('result_screen').style.display = 'block';
  });

  document.getElementById('button_restart')?.addEventListener('click', () => {
    document.getElementById('start_screen').style.display = 'block';
    document.getElementById('game_screen').style.display = 'none';
    document.getElementById('result_screen').style.display = 'none';
  });
})();
`;

  return {
    status: "ready",
    clientJS,
  };
}

